import{_ as t,o as e,c as r,ag as o}from"./chunks/framework.DoUXNnsN.js";const u=JSON.parse('{"title":"CSharp","description":"","frontmatter":{"title":"CSharp","aliases":["C#","C Sharp","C#入门","C#学习路径"],"tags":["编程语言","CSharp"],"status":"ai-draft","sources":["https://learn.microsoft.com/zh-cn/dotnet/csharp/","https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/configure-language-version","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"20-编程语言/CSharp/CSharp.md","filePath":"20-编程语言/CSharp/CSharp.md"}'),l={name:"20-编程语言/CSharp/CSharp.md"};function d(i,a,h,n,c,p){return e(),r("div",null,[...a[0]||(a[0]=[o('<blockquote><p>本篇是 C# 系列的总览页。读完你应该能：说清 C# 和 .NET 各是什么、它们怎么配合；知道这 15 篇该按什么顺序看；知道每一篇学完能做什么。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>C#（读作 C Sharp）</strong> 是微软设计的一门现代、强类型、面向对象的编程语言；它写出来的程序运行在 <strong>.NET</strong> 平台上。你们公司的 MES、WMS、QMS 用的就是它，所以它是你&quot;写业务系统&quot;的主力语言。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><p>几乎不需要。只要你会开关电脑、会打开命令行（PowerShell 就行）。如果你完全没写过代码，建议先翻一下 <a href="/Encyclopedia/20-编程语言/编程语言">编程语言</a> 里&quot;通用概念对照&quot;那一节，知道&quot;变量、函数、循环&quot;是什么。已经会 <a href="/Encyclopedia/20-编程语言/Python/Python">Python</a> 的话，可以把本系列当作&quot;换一门语言再学一遍&quot;，速度会很快。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>工厂信息化系统（工单、物料、扫码、报表）需要一门语言：</p><ul><li>能写<strong>界面</strong>（WinForms、WPF）和<strong>网站接口</strong>（ASP.NET Core Web API）；</li><li>能连 <strong>SQL Server</strong>，并有成熟的 ORM（对象关系映射，把数据库的表当成代码里的对象用，如 <a href="/Encyclopedia/30-.NET生态/SqlSugar">SqlSugar</a>）；</li><li>能和设备打交道（串口、TCP、Modbus），见 <a href="/Encyclopedia/30-.NET生态/CSharp串口通信">CSharp串口通信</a>、<a href="/Encyclopedia/30-.NET生态/CSharp-TCP通信">CSharp-TCP通信</a>；</li><li><strong>类型检查严格</strong>：很多低级错误在编译时就报出来，而不是等产线上跑起来才崩。</li></ul><p>C# 在这几点上都很强，而且微软持续更新，社区资料极多。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="c-和-net-的关系" tabindex="-1">C# 和 .NET 的关系 <a class="header-anchor" href="#c-和-net-的关系" aria-label="Permalink to &quot;C# 和 .NET 的关系&quot;">​</a></h3><p>新手最容易混淆这两个词。用厨房打比方：</p><table tabindex="0"><thead><tr><th>名词</th><th>比喻</th><th>实际是什么</th></tr></thead><tbody><tr><td>C#</td><td>菜谱的文字和语法</td><td>一门语言，规定怎么写代码</td></tr><tr><td>编译器（Roslyn）</td><td>把菜谱翻译成操作步骤的人</td><td>把 <code>.cs</code> 源文件编译成 IL（中间语言），装进 <code>.dll</code> / <code>.exe</code></td></tr><tr><td>.NET 运行时（CLR）</td><td>厨房和厨师</td><td>真正执行 IL 的环境：把 IL 即时翻译成机器码（JIT），并管理内存（垃圾回收）</td></tr><tr><td>基础类库（BCL）</td><td>厨房里现成的锅碗瓢盆</td><td><code>List</code>、<code>File</code>、<code>HttpClient</code> 等现成功能</td></tr><tr><td>SDK</td><td>整套厨房装修工具包</td><td>编译器 + 命令行工具 <code>dotnet</code> + 模板</td></tr></tbody></table><p>所以：<strong>C# 是语言，.NET 是平台</strong>。.NET 也能跑 F#、VB，C# 也只有在 .NET 上才有意义。详见 <a href="/Encyclopedia/30-.NET生态/dotNET">dotNET</a> 和 <a href="/Encyclopedia/30-.NET生态/dotNET运行时与SDK">dotNET运行时与SDK</a>。</p><p>本机验证：<code>dotnet --version</code> 输出 <code>10.0.401</code>，说明装的是 .NET 10 SDK；它自带的 C# 编译器默认使用 <strong>C# 14</strong>（在代码里写一行 <code>#error version</code> 编译，报错信息里会写&quot;语言版本: 14.0&quot;）。本系列所有代码都在这个版本上实际运行过。</p><h3 id="一个源文件的一生" tabindex="-1">一个源文件的一生 <a class="header-anchor" href="#一个源文件的一生" aria-label="Permalink to &quot;一个源文件的一生&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Program.cs  --(Roslyn 编译器)--&gt;  MesHello.dll (IL)  --(CLR 的 JIT)--&gt;  CPU 执行</span></span></code></pre></div><p><code>dotnet build</code> 做第一步，<code>dotnet run</code> 是&quot;先 build 再运行&quot;。你在 <a href="/Encyclopedia/20-编程语言/CSharp/CSharp环境与第一个程序">CSharp环境与第一个程序</a> 里会亲手做。</p><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><p>15 篇按下面的顺序看。每一篇都有可运行的例子，例子都贴着工厂（工单、板码、良率、物料）。</p><p><strong>第一阶段：语言基础（必看，约一周）</strong></p><ol><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp环境与第一个程序">CSharp环境与第一个程序</a>：装好 SDK，跑出第一行输出，认识项目结构。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp类型与变量">CSharp类型与变量</a>：int、decimal、string、值类型与引用类型、null。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp控制流与方法">CSharp控制流与方法</a>：if/switch/循环，写方法，ref/out。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp类与对象">CSharp类与对象</a>：类、属性、构造函数、record、struct。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp继承多态与接口">CSharp继承多态与接口</a>：继承、abstract、interface、组合。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp集合与泛型">CSharp集合与泛型</a>：List、Dictionary、HashSet、泛型。</li></ol><p><strong>第二阶段：写真实程序要用的能力（约两周）</strong></p><ol start="7"><li><a href="/Encyclopedia/20-编程语言/CSharp/LINQ">LINQ</a>：用一行代码做过滤、分组、统计，写报表逻辑必备。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp委托事件与Lambda">CSharp委托事件与Lambda</a>：把&quot;一段动作&quot;当参数传，理解事件通知。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp异常处理">CSharp异常处理</a>：出错了怎么办，try/catch/finally。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp字符串处理">CSharp字符串处理</a>：拆条码、拼 SQL 参数、格式化。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp文件与IO">CSharp文件与IO</a>：读写文本、CSV、日志文件。</li></ol><p><strong>第三阶段：进阶（做设备通信、高并发时再来）</strong></p><ol start="12"><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp异步编程">CSharp异步编程</a>：async/await，界面不卡、接口不堵。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp多线程与锁">CSharp多线程与锁</a>：线程、lock、并发集合；对照 <a href="/Encyclopedia/10-计算机基础/操作系统/并发与锁">并发与锁</a>。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp反射与特性">CSharp反射与特性</a>：运行时读类型信息；ORM 的 <code>[SugarColumn]</code> 就是特性。</li><li>回到 <a href="/Encyclopedia/30-.NET生态/dotNET">dotNET</a>，选 WinForms / Web API / 后台服务继续走。</li></ol><blockquote><p>学习建议：每篇的&quot;动手实验&quot;代码都复制到本机跑一遍，改一个数字再跑一遍。看懂和写出来之间差着十次敲键盘。</p></blockquote><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>确认你的电脑能编译运行 C#（后面所有篇章都要用）：</p><ol><li>打开 PowerShell，输入 <code>dotnet --version</code>，应看到类似 <code>10.0.401</code> 的版本号（具体数字可能不同，主版本是 10 即可）。</li><li>输入 <code>dotnet --list-sdks</code>，能看到一行 SDK 及安装路径。</li><li>如果提示&quot;不是内部或外部命令&quot;，说明没装 SDK，见 <a href="/Encyclopedia/20-编程语言/CSharp/CSharp环境与第一个程序">CSharp环境与第一个程序</a> 的&quot;安装&quot;一节。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>办法</th></tr></thead><tbody><tr><td>把 C# 和 .NET 当成一回事，搜资料时看不懂</td><td>两者是两层</td><td>记住：语法问题查&quot;C# 语言&quot;，类库问题查&quot;.NET API&quot;</td></tr><tr><td>教程里的代码在自己机器上编译报错</td><td>教程是老版本（.NET Framework 4.x、没有顶级语句）</td><td>看教程发布时间；老项目是 .NET Framework，新项目是 .NET 6+</td></tr><tr><td>不知道该学哪个界面技术</td><td>范围太大</td><td>先学完第一阶段，再按公司项目选 WinForms/WPF/Web</td></tr></tbody></table><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><ul><li><strong>业务视角</strong>：MES 里&quot;工单下达、过站、报工&quot;这些业务规则，最终都落成 C# 的类和方法。语言学得扎实，才能读懂并改自己公司系统的代码。</li><li><strong>技术视角</strong>：公司系统多半是 .NET Framework 4.x 或 .NET 6/8 的存量项目，语法比本系列用的新版本旧一些（例如没有顶级语句、没有 record）。写法不同但概念完全一致；遇到旧写法就当&quot;同一件事的老方言&quot;。具体版本请对照你们系统核实。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>C# 和 .NET 哪个是语言，哪个是平台？ <strong>答</strong>：C# 是语言，.NET 是平台（运行时 + 类库 + 工具）。</li><li><code>.cs</code> 文件被编译后变成什么？谁来执行它？ <strong>答</strong>：变成包含 IL 的 <code>.dll</code>/<code>.exe</code>；由 .NET 运行时（CLR）通过 JIT 翻译成机器码执行。</li><li>为什么说&quot;C# 编译期就能查出很多错误&quot;对工厂系统有价值？ <strong>答</strong>：强类型让&quot;把字符串当数字用&quot;这类错误在编译时就报出，避免上线后才在产线上出问题。</li><li>本系列第二阶段为什么先学 LINQ 再学异步？ <strong>答</strong>：LINQ 几乎每个业务程序都在用（查询、统计），而异步主要在界面不卡顿、接口高并发时才必需，属于进阶。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>C# 是语言，.NET 是平台；本系列用 .NET 10 SDK + C# 14。</li><li>15 篇分三阶段：基础六篇，实用五篇，进阶四篇。</li><li>所有例子在本机实际运行，亲手敲一遍最有效。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/30-.NET生态/dotNET">dotNET</a>、<a href="/Encyclopedia/30-.NET生态/dotNET运行时与SDK">dotNET运行时与SDK</a>、<a href="/Encyclopedia/20-编程语言/编程语言">编程语言</a>、<a href="/Encyclopedia/20-编程语言/Python/Python">Python</a>、<a href="/Encyclopedia/30-.NET生态/SqlSugar">SqlSugar</a>、<a href="/Encyclopedia/20-编程语言/编程范式">编程范式</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>微软官方 C# 文档（中文）：<a href="https://learn.microsoft.com/zh-cn/dotnet/csharp/" target="_blank" rel="noreferrer">https://learn.microsoft.com/zh-cn/dotnet/csharp/</a></li><li>配置 C# 语言版本（说明默认版本跟随目标框架）：<a href="https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/configure-language-version" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/configure-language-version</a></li></ul>',42)])])}const C=t(l,[["render",d]]);export{u as __pageData,C as default};
